                        const bonusText = extraStatPoints > 0 || extraSkillPoints > 0
                            ? `（含天赋加成：+${extraStatPoints}属性点、+${extraSkillPoints}技能点）`
                            : '';
                        if (typeof toastr !== 'undefined') {
                            toastr.success(`等级提升至 ${newLevel}！获得 ${attributePointsGained} 属性点、${skillPointsGained} 技能点${bonusText}`, '🎉 升级！', { timeOut: 3000 });
                        }
                    }
                }
            }
            catch (error) {
                console.error('[状态栏] 自动升级检查失败:', error);
            }
